=== CLAIM OFFICE ===
     1	const PROCESSING_FEE_G = 5;
     2	
     3	// The spec's component taxonomy, open-ended by its own wording ("components --
     4	// for example runes and moonstones"). This is where a new component type is
     5	// declared; it must also get a price-list row below, which the price lookup
     6	// enforces for every quoted type.
     7	const COMPONENT_TYPES: ReadonlySet<string> = new Set(["rune", "moonstone"]);
     8	
     9	// The spec states one component tariff for all components ("insured at 250 G
    10	// each, with a base premium of 25 G per component"), so every component row
    11	// carries it.
    12	const COMPONENT_BASE_PREMIUM_G = 25;
    13	
    14	const BASE_PREMIUM_G: Readonly<Record<string, number>> = {
    15	  sword: 100,
    16	  amulet: 60,
    17	  staff: 80,
    18	  potion: 40,
    19	  rune: COMPONENT_BASE_PREMIUM_G,
    20	  moonstone: COMPONENT_BASE_PREMIUM_G,
    21	};
    22	
    23	const ALIKE_BLOCK_SIZE = 3;
    24	const ALIKE_BLOCK_BASE_PREMIUM_G = 60;
    25	
    26	export interface Customer {
    27	  readonly yearsWithMHPCO: number;
    28	}
    29	
    30	export interface Item {
    31	  readonly type: string;
    32	  readonly cursed?: boolean;
    33	  readonly enchantment?: number;
    34	}
    35	
    36	// Resolves the spec's open question on "alike" -- exactly the same type, or
    37	// just the same family? -- in favour of identical type. The spec's
    38	// mixed-component examples decide it; the specs assert them.
    39	function groupAlikeItems(items: readonly Item[]): Map<string, number> {
    40	  const counts = new Map<string, number>();
    41	  for (const item of items) {
    42	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
    43	  }
    44	  return counts;
    45	}
    46	
    47	function isComponent(type: string): boolean {
    48	  return COMPONENT_TYPES.has(type);
    49	}
    50	
    51	// Eligibility for the building-block offer, resolving two spec readings:
    52	//   - exactly ALIKE_BLOCK_SIZE, not repeating within a larger count -- the
    53	//     spec's 4-rune and 7-rune examples rule out charging a second block;
    54	//   - components only -- the spec offers the block for "3 alike components",
    55	//     so three swords are three swords.
    56	// The specs assert all of these.
    57	function formsAlikeBlock(type: string, count: number): boolean {
    58	  return count === ALIKE_BLOCK_SIZE && isComponent(type);
    59	}
    60	
    61	// The price-list tariff for a single item of this type, before any
    62	// building-block offer and before any item-specific surcharge.
    63	function itemBasePremium(type: string): number {
    64	  return BASE_PREMIUM_G[type];
    65	}
    66	
    67	function alikeItemsBasePremium(type: string, count: number): number {
    68	  if (formsAlikeBlock(type, count)) {
    69	    return ALIKE_BLOCK_BASE_PREMIUM_G;
    70	  }
    71	  return count * itemBasePremium(type);
    72	}
    73	
    74	export function policyBasePremium(items: readonly Item[]): number {
    75	  let total = 0;
    76	  for (const [type, count] of groupAlikeItems(items)) {
    77	    total += alikeItemsBasePremium(type, count);
    78	  }
    79	  return total;
    80	}
    81	
    82	const CURSE_SURCHARGE_RATE = 0.5;
    83	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
    84	
    85	// The premium side's own "highly enchanted" threshold. The claim rules use a
    86	// separate, independently changeable enchantment threshold for reimbursement,
    87	// so this constant is named for the surcharge it governs and must not be
    88	// shared with it.
    89	const HIGH_ENCHANTMENT_SURCHARGE_LEVEL = 5;
    90	
    91	// "Highly enchanted" in the premium sense. An item may carry no enchantment
    92	// level at all -- the spec gives components (runes, moonstones) neither an
    93	// enchantment level nor a material -- and an absent level is not a high one.
    94	function isHighlyEnchanted(item: Item): boolean {
    95	  return item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_SURCHARGE_LEVEL;
    96	}
    97	
    98	// The risk the MHPCO prices into one individual item, in G -- charged on that
    99	// item's own base premium, not on the policy total. The spec lists two such
   100	// surcharges (curse, high enchantment) and they stack: a cursed sword at
   101	// enchantment 5 costs 180 G, not the 150 G a highest-clause-wins rule would
   102	// charge. Clause set and stacking rule change together here, because each
   103	// premium-side clause is stated as an "add" clause; the claim side composes
   104	// its own clauses by precedence instead, so that rule is not shared with this
   105	// one. This is the one place a premium-side item risk clause is declared.
   106	//
   107	// The clauses are charged on "the base premium of the affected item", and this
   108	// is the one place that phrase is given a meaning: the single-item price-list
   109	// tariff. The spec leaves the phrase open for a component inside a building
   110	// block, since the block replaces the members' separate tariffs with one block
   111	// price; the reading adopted here charges the member's own tariff rather than a
   112	// share of the block price, because the spec treats the block as an aggregate
   113	// discount on the premium that is not pushed down into per-item figures. The
   114	// specs pin it.
   115	function itemRiskSurcharge(item: Item): number {
   116	  let rate = 0;
   117	  if (item.cursed === true) {
   118	    rate += CURSE_SURCHARGE_RATE;
   119	  }
   120	  if (isHighlyEnchanted(item)) {
   121	    rate += HIGH_ENCHANTMENT_SURCHARGE_RATE;
   122	  }
   123	  return itemBasePremium(item.type) * rate;
   124	}
   125	
   126	// The premium stage between the two modifier scopes the spec distinguishes:
   127	// item-specific surcharges have been applied to the base premium of each
   128	// affected item; policy-wide modifiers and the fee have not been applied yet.
   129	export function premiumAfterItemModifiers(items: readonly Item[]): number {
   130	  let total = policyBasePremium(items);
   131	  for (const item of items) {
   132	    total += itemRiskSurcharge(item);
   133	  }
   134	  return total;
   135	}
   136	
   137	const LOYALTY_DISCOUNT_RATE = 0.2;
   138	const LOYALTY_DISCOUNT_MIN_YEARS = 2;
   139	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
   140	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
   141	
   142	// "Long-standing" in the spec's own words -- the category of customer the
   143	// loyalty discount is offered to ("long-standing customers (>= 2 years of
   144	// business with MHPCO)"). Who qualifies is a separate decision from what the
   145	// policy-wide clauses add up to: the MHPCO could redefine the category (count
   146	// anniversaries rather than calendar years, or require a prior contract)
   147	// without touching any clause's rate. This is the one place that category is
   148	// decided. The threshold is a floor, so exactly 2 years qualifies.
   149	function isLongStandingCustomer(customer: Customer): boolean {
   150	  return customer.yearsWithMHPCO >= LOYALTY_DISCOUNT_MIN_YEARS;
   151	}
   152	
   153	// A contract "after their first", in the spec's own words -- the position in the
   154	// customer's history that the follow-up discount is offered for ("customers
   155	// receive a 15 % discount on each contract after their first"). Which contracts
   156	// count towards "their first" is a separate decision from what the clause is
   157	// worth: the MHPCO could stop counting lapsed or cancelled policies, or count
   158	// only contracts of the same item class, without touching any clause's rate.
   159	// This is the one place that position is decided. Having any previous contract
   160	// at all is enough, so the second contract already qualifies.
   161	function isFollowUpContract(previousContracts: number): boolean {
   162	  return previousContracts > 0;
   163	}
   164	
   165	// The net rate of the spec's three policy-wide clauses: first insurance,
   166	// loyalty and the follow-up-contract discount. Each is stated as a signed
   167	// percentage and they compose additively, so one net rate carries them; this is
   168	// the one place a policy-wide clause is declared. Discounts subtract.
   169	//
   170	// The first-insurance surcharge has no guard because every quote qualifies: the
   171	// spec's second integration example rules that "each item in a `quote` is
   172	// treated as a first insurance, regardless of customer history". The absent
   173	// predicate is that ruling, not an unhandled case. The specs pin it.
   174	//
   175	// The clause is charged once on the policy base premium even though the spec
   176	// words it per item. No test can tell the two readings apart, which is the
   177	// point: the policy base is the sum of the item bases and the rate is uniform,
   178	// so 10 % of the sum equals the sum of the per-item 10 %s.
   179	function policyModifierRate(customer: Customer, previousContracts: number): number {
   180	  let rate = FIRST_INSURANCE_SURCHARGE_RATE;
   181	  if (isLongStandingCustomer(customer)) {
   182	    rate -= LOYALTY_DISCOUNT_RATE;
   183	  }
   184	  if (isFollowUpContract(previousContracts)) {
   185	    rate -= FOLLOW_UP_CONTRACT_DISCOUNT_RATE;
   186	  }
   187	  return rate;
   188	}
   189	
   190	// What the policy-wide clauses add to (or take off) the premium, in G -- the
   191	// counterpart of itemRiskSurcharge on the other modifier scope. The two scopes
   192	// are charged on different bases, and this is the one place the policy-wide
   193	// base is fixed: the policy base premium, NOT the premium after item
   194	// surcharges. The spec's integration examples settle it -- the 3-year second
   195	// contract is 100 + 50 + 30 - 20 + 10 - 15, where the -20 loyalty is 20 % of
   196	// the 100 G base, not of the 180 G running total.
   197	function policyModifierTotal(
   198	  customer: Customer,
   199	  items: readonly Item[],
   200	  previousContracts: number,
   201	): number {
   202	  return policyBasePremium(items) * policyModifierRate(customer, previousContracts);
   203	}
   204	
   205	// The premium once both of the spec's modifier scopes have been priced, before
   206	// the fee. Each scope contributes a surcharge pool charged on its own base.
   207	export function premiumBeforeFee(
   208	  customer: Customer,
   209	  items: readonly Item[],
   210	  previousContracts: number,
   211	): number {
   212	  return (
   213	    premiumAfterItemModifiers(items) +
   214	    policyModifierTotal(customer, items, previousContracts)
   215	  );
   216	}
   217	
   218	export function quote(
   219	  customer: Customer,
   220	  items: readonly Item[],
   221	  previousContracts: number,
   222	): number {
   223	  return PROCESSING_FEE_G;
   224	}

