    82	  describe("quote — item-specific modifiers", () => {
    83	    it("adds a 50 % curse surcharge to a cursed sword's base premium — premium 160 G before fee", () => {
    84	      expect(
    85	        premiumAfterItemModifiers([{ type: "sword", cursed: true }]),
    86	      ).toBe(150);
